mapper.select:
SELECT tn.id AS task_node_id, tn.task_id, tn.node_id AS current_node_id, tn.node_name, tn.node_type, t.task_name, t.template_id, t.create_time AS task_create_time, tpl.template_name, n.node_tips,
CASE WHEN EXISTS ( SELECT 1 FROM flow_task_node p WHERE p.task_id = tn.task_id AND p.handler_user_id = #{handlerUserId} AND p.submit_status = 0 ) THEN 0 ELSE 1 END AS todo_status FROM flow_task_node tn INNER JOIN flow_task t ON tn.task_id = t.id LEFT JOIN flow_template tpl ON t.template_id = tpl.id LEFT JOIN flow_template_node n ON tn.node_id = n.id WHERE tn.handler_user_id = #{handlerUserId} AND t.status IN (1, 2)
AND tn.id = ( SELECT MAX(t2.id) FROM flow_task_node t2 WHERE t2.task_id = tn.task_id AND t2.handler_user_id = #{handlerUserId} ) ORDER BY tn.create_time DESC LIMIT #{offset}, #{limit}
